/**
 * @file mujoco_sim.hpp
 * @brief ROS-free wrapper around one MuJoCo model: joint commands in, joint state and tool wrench out.
 * @details The ros2_control plugin (MujocoSystemInterface) is a thin shell over this class, so the
 *          physics side is testable without a controller manager. Built against MuJoCo 4.x.
 *
 *          Joint model: every commanded joint has one MuJoCo position actuator (generated by the
 *          MJCF generator). A command (position q*, velocity v*) is applied as
 *              ctrl = q* + (kv / kp) * v*
 *          which, for the actuator force kp (ctrl - q) - kv qdot, equals the PD law
 *          kp (q* - q) + kv (v* - qdot): velocity feed-forward without a second actuator.
 *
 *          Raw sensor wrench (what a real F/T sensor reports): MuJoCo's force and torque sensors on
 *          the site `ft_sensor` (the wrist, origin of the tool mount), in the SITE frame, multiplied by
 *          -1. Measured convention (test_mujoco_sim.cpp, WeightAndPush): the result is the force the
 *          tool side exerts on the sensor, i.e. F_env + m g (environment force on the tool plus the
 *          weight, plus inertial terms, of everything beyond the sensor), torque about the site
 *          origin. A tool hanging free at rest reads (0, 0, -m g) when the site z axis points up.
 *          Nothing is compensated or moved to another frame; that is the job of a downstream
 *          conditioner. An optional tare only subtracts a stored reading.
 *
 *          Ground truth (evaluation only): sum of mj_contactForce over contacts between a geom of
 *          the tool subtree (bodies at and beyond the F/T site's body) and any other geom, as the
 *          wrench the environment exerts on the tool, referred to the origin of site `tcp_site`
 *          and expressed in that site's frame (the tcp_link convention).
 */

#pragma once

#include <algorithm>
#include <array>
#include <map>
#include <random>
#include <string>
#include <vector>

#include <mujoco/mujoco.h>

namespace sim_mujoco
{

using Wrench = std::array<double, 6>;  ///< fx fy fz tx ty tz

class MujocoSim
{
public:
  /// Loads the MJCF at `mjcf_path`. Throws std::runtime_error on any model or name error.
  MujocoSim(
    const std::string & mjcf_path, const std::vector<std::string> & joints,
    const std::string & ft_site = "ft_sensor",
    const std::string & tcp_site = "tcp_site");
  ~MujocoSim();
  MujocoSim(const MujocoSim &) = delete;
  MujocoSim & operator=(const MujocoSim &) = delete;

  size_t jointCount() const {return joint_.size();}
  double timestep() const {return model_->opt.timestep;}

  /// Set the commanded joints' positions (rad or m) and velocities zero, then re-satisfy the
  /// model's mimic (joint equality) constraints and run forward kinematics.
  void setJointPositions(const std::vector<double> & q);

  /// Position / velocity command of joint i (as ordered in the constructor). NaN means "none":
  /// a NaN position holds the last valid target, a NaN velocity counts as zero.
  void setCommand(size_t i, double position, double velocity);

  /// Feed-forward torque (N m, N for a prismatic joint) for joint i, held until changed. Applied as
  /// ctrl += tau / kp, so the actuator force gains exactly tau (the force range still clamps it).
  void setFeedforward(size_t i, double tau);

  /// True if any body in the model has gravcomp set (it would double-count a gravity feed-forward).
  bool hasGravcomp() const;

  /// Advance the simulation by `dt` seconds (rounded down to whole MuJoCo steps; the remainder is
  /// carried to the next call). Returns the number of steps taken.
  int advance(double dt);

  double position(size_t i) const {return data_->qpos[joint_[i].qpos_adr];}
  double velocity(size_t i) const {return data_->qvel[joint_[i].dof_adr];}
  /// Applied actuator force (N or N m, after the force range clamp).
  double effort(size_t i) const {return data_->actuator_force[joint_[i].actuator];}
  double target(size_t i) const {return joint_[i].target;}

  /// Raw F/T sensor wrench (see above), tare removed.
  Wrench wrench() const;
  /// Store the current raw reading as the zero point.
  void tareWrench();
  void clearTare() {tare_.fill(0.0);}

  /// Ground-truth contact wrench on the tool at tcp_site, in the tcp_site frame (not for control).
  Wrench groundTruthWrench() const;
  /// One entry per tool/environment contact (geom and body names, normal force), for diagnostics.
  std::string describeToolContacts() const;

  /// Contacts that should not happen in a coverage pass: robot body against robot body (self collision, tool included)
  /// or a non-tool robot body against the world geoms (an arm link on the wall or an obstacle). The tool against the
  /// world is the intended contact and is not listed. Only penetrating contacts (dist < 0) count. Call once per
  /// step; the first sighting of a body pair is returned in `new_pairs` ("A <-> B [self|link_world] depth=..") and
  /// every sighting is counted for unexpectedContactSummary().
  void scanUnexpectedContacts(std::vector<std::string> & new_pairs);
  /// "none" or one line per pair: steps seen and deepest penetration.
  std::string unexpectedContactSummary() const;

  /// Planar base (present when the MJCF has base_x_joint, base_y_joint, base_yaw_joint).
  bool hasBase() const {return base_.present;}
  /// Body-frame velocity command (vx, vy, wz), limited to the MJCF's velocity limits; vy is
  /// dropped for a diff drive. Held until changed (the caller applies its own timeout).
  void setBaseVelocity(double vx, double vy, double wz);
  struct BasePose
  {
    double x, y, yaw;      ///< world (odom) frame
    double vx, vy, wz;     ///< body frame
  };
  BasePose basePose() const;

  /// Simulated depth sensor (present when the MJCF has the site `depth_sensor` and the numeric
  /// `sim_mujoco_depth`, see the generator's `depth_sensor` option). Ray-cast depth: a width x
  /// height pinhole grid of mj_multiRay from the site, against the world geoms (group 1: the
  /// scene, not the robot itself) only. Points are in the SITE frame (x forward, y left, z up).
  struct DepthConfig
  {
    int width{0};
    int height{0};
    double hfov{0.0};       ///< rad
    double vfov{0.0};       ///< rad
    double min_range{0.0};  ///< m
    double max_range{0.0};  ///< m
    double rate_hz{0.0};
    double noise_std{0.0};  ///< Gaussian noise on the range, m (fixed seed)
  };
  bool hasDepth() const {return depth_.present;}
  const DepthConfig & depthConfig() const {return depth_.cfg;}
  /// One scan: the hit points (misses and ranges outside [min_range, max_range] are dropped).
  std::vector<std::array<float, 3>> depthScan();

  double time() const {return data_->time;}
  int contactCount() const {return data_->ncon;}
  const mjModel * model() const {return model_;}
  const mjData * data() const {return data_;}

private:
  struct Joint
  {
    int qpos_adr{0};
    int dof_adr{0};
    int actuator{0};
    double kv_over_kp{0.0};
    double kp{0.0};
    double target{0.0};
    double feedforward{0.0};
  };
  struct Base
  {
    bool present{false};
    bool diff{false};
    double max_linear{0.5};
    double max_angular{1.0};
    int qpos_adr[3]{};
    int dof_adr[3]{};
    int actuator[3]{};
    double kv_over_kp[3]{};
    double target[3]{};    ///< x, y, yaw set points, integrated from the velocity command
    double cmd[3]{};       ///< body-frame command
  };
  void initBase();
  void initDepth();
  Wrench rawWrench() const;
  void applyMimic();

  mjModel * model_{nullptr};
  mjData * data_{nullptr};
  std::vector<Joint> joint_;
  std::vector<double> velocity_command_;
  int tcp_site_{-1};
  std::vector<char> tool_body_;
  struct PairStat {long steps{0}; double depth{0.0}; std::string kind;};
  std::map<std::string, PairStat> unexpected_;
  int force_adr_{-1};
  int torque_adr_{-1};
  Wrench tare_{};
  Base base_;
  struct Depth
  {
    bool present{false};
    int site{-1};
    DepthConfig cfg;
    std::vector<mjtNum> dirs;       ///< unit ray directions in the site frame, 3 per ray
    std::vector<mjtNum> world_dirs;
    std::vector<mjtNum> dist;
    std::vector<int> geomid;
    std::mt19937 rng{12345};
  };
  Depth depth_;
  double carry_{0.0};
};

}  // namespace sim_mujoco
